// ── Styled .xlsx builder (pure JS, no dependency) ─────────────────────────
// Builds a real Office Open XML spreadsheet as a stored zip, so we can produce
// a formatted Excel file (fills, borders, bold, currency) that mirrors the PDF
// — without the `xlsx` npm package (which broke the build). Cells:
//   {v, t:'n'|'s', s:styleIndex}. Styles: 0 plain, 1 title, 2 header,
//   3 currency, 4 bold, 5 currency-bold, 6 subtle, 7 currency-red.
const _CRC=(()=>{const t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function _crc32(buf){let c=0xFFFFFFFF;for(let i=0;i<buf.length;i++)c=_CRC[(c^buf[i])&0xFF]^(c>>>8);return (c^0xFFFFFFFF)>>>0;}
function _u8(s){return new TextEncoder().encode(s);}
function _zip(files){
  const chunks=[],central=[];let offset=0;
  const u16=n=>[n&0xFF,(n>>8)&0xFF],u32=n=>[n&0xFF,(n>>8)&0xFF,(n>>16)&0xFF,(n>>24)&0xFF];
  for(const f of files){
    const nm=_u8(f.name),data=f.data,crc=_crc32(data);
    chunks.push(new Uint8Array([0x50,0x4b,0x03,0x04,...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(nm.length),...u16(0)]));
    chunks.push(nm);chunks.push(data);
    central.push({h:new Uint8Array([0x50,0x4b,0x01,0x02,...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(nm.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset)]),nm});
    offset+=30+nm.length+data.length;
  }
  const cStart=offset;let cSize=0;
  for(const c of central){chunks.push(c.h);chunks.push(c.nm);cSize+=c.h.length+c.nm.length;}
  chunks.push(new Uint8Array([0x50,0x4b,0x05,0x06,...u16(0),...u16(0),...u16(central.length),...u16(central.length),...u32(cSize),...u32(cStart),...u16(0)]));
  let total=0;for(const c of chunks)total+=c.length;
  const out=new Uint8Array(total);let p=0;for(const c of chunks){out.set(c,p);p+=c.length;}
  return out;
}
function _xlColLetter(n){let s="";n++;while(n>0){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=Math.floor((n-1)/26);}return s;}
function _xlEsc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
const _XLSX_STYLES=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="&quot;$&quot;#,##0.00"/></numFmts><fonts count="6"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="16"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font><font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font><font><sz val="10"/><color rgb="FF888888"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFDC2626"/><name val="Calibri"/></font></fonts><fills count="5"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF0F1F35"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF2E8C96"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF3F4F6"/></patternFill></fill></fills><borders count="3"><border><left/><right/><top/><bottom/></border><border><left style="thin"><color rgb="FFDDDDDD"/></left><right style="thin"><color rgb="FFDDDDDD"/></right><top style="thin"><color rgb="FFDDDDDD"/></top><bottom style="thin"><color rgb="FFDDDDDD"/></bottom></border><border><left style="thin"><color rgb="FFDDDDDD"/></left><right style="thin"><color rgb="FFDDDDDD"/></right><top style="double"><color rgb="FF282828"/></top><bottom style="thin"><color rgb="FFDDDDDD"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="11"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="center"/></xf><xf numFmtId="0" fontId="2" fillId="3" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="0" fontId="3" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="164" fontId="3" fillId="4" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="0" fontId="4" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="164" fontId="5" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="0" fontId="3" fillId="4" borderId="2" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="164" fontId="3" fillId="4" borderId="2" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
// Style indices for callers: TITLE=1 HEADER=2 CURRENCY=3 BOLD=4 CURRENCY_BOLD=5 SUBTLE=6 CURRENCY_RED=7 BORDERED=8
const XS={TITLE:1,HEADER:2,CUR:3,BOLD:4,CURBOLD:5,SUBTLE:6,CURRED:7,CELL:8,TOTBOLD:9,TOTCUR:10};
function _xlSheet(rows,merges,colWidths){
  let body="";
  rows.forEach((row,ri)=>{
    let cells="";
    (row||[]).forEach((cell,ci)=>{
      if(cell==null)return;
      const ref=`${_xlColLetter(ci)}${ri+1}`;const s=cell.s?` s="${cell.s}"`:"";
      if(cell.t==="n")cells+=`<c r="${ref}"${s}><v>${cell.v}</v></c>`;
      else cells+=`<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${_xlEsc(cell.v==null?"":cell.v)}</t></is></c>`;
    });
    body+=`<row r="${ri+1}">${cells}</row>`;
  });
  const cols=(colWidths||[]).map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}"/>`).join("");
  const mergeXml=(merges&&merges.length)?`<mergeCells count="${merges.length}">${merges.map(m=>`<mergeCell ref="${m}"/>`).join("")}</mergeCells>`:"";
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">${cols?`<cols>${cols}</cols>`:""}<sheetData>${body}</sheetData>${mergeXml}</worksheet>`;
}
// Public: build+download a styled xlsx. rows = array of arrays of cell objects.
function downloadXLSX(filename,rows,{merges=[],colWidths=[],sheetName="Report"}={}){
  const files=[
    {name:"[Content_Types].xml",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`)},
    {name:"_rels/.rels",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`)},
    {name:"xl/workbook.xml",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${_xlEsc(sheetName)}" sheetId="1" r:id="rId1"/></sheets></workbook>`)},
    {name:"xl/_rels/workbook.xml.rels",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`)},
    {name:"xl/styles.xml",data:_u8(_XLSX_STYLES)},
    {name:"xl/worksheets/sheet1.xml",data:_u8(_xlSheet(rows,merges,colWidths))},
  ];
  const zip=_zip(files);
  const blob=new Blob([zip],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
  const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(()=>URL.revokeObjectURL(url),1000);
}
// Multi-sheet variant: sheets = [{name, rows, merges?, colWidths?}] — same
// cell objects and style indices as downloadXLSX, one workbook, many tabs.
function downloadXLSXSheets(filename,sheets){
  const overrides=sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join("");
  const sheetTags=sheets.map((sh,i)=>`<sheet name="${_xlEsc(String(sh.name||("Sheet"+(i+1))).slice(0,31))}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join("");
  const relTags=sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join("");
  const files=[
    {name:"[Content_Types].xml",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${overrides}<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`)},
    {name:"_rels/.rels",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`)},
    {name:"xl/workbook.xml",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheetTags}</sheets></workbook>`)},
    {name:"xl/_rels/workbook.xml.rels",data:_u8(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${relTags}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`)},
    {name:"xl/styles.xml",data:_u8(_XLSX_STYLES)},
    ...sheets.map((sh,i)=>({name:`xl/worksheets/sheet${i+1}.xml`,data:_u8(_xlSheet(sh.rows,sh.merges||[],sh.colWidths||[]))})),
  ];
  const zip=_zip(files);
  const blob=new Blob([zip],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
  const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(()=>URL.revokeObjectURL(url),1000);
}
// Styled-report scaffold: consistent title banner, section bands, KPI
// blocks and bordered tables for every downloadable XLSX report.
function rptScaffold(ncols){
  const rows=[];const merges=[];
  const colL=n=>_xlColLetter(n-1);
  const pad=(cells,st)=>{const r=[...cells];while(r.length<ncols)r.push(st!=null?{v:"",s:st}:null);return r;};
  return {
    rows,merges,
    title(t,sub){
      rows.push([{v:t,s:XS.TITLE}]);merges.push(`A1:${colL(ncols)}1`);
      rows.push([{v:sub,s:XS.SUBTLE}]);merges.push(`A2:${colL(ncols)}2`);
      rows.push([]);
    },
    section(label){
      rows.push(pad([{v:label,s:XS.HEADER}],XS.HEADER));
      merges.push(`A${rows.length}:${colL(ncols)}${rows.length}`);
    },
    kpi(label,cell){rows.push([{v:label,s:XS.BOLD},cell]);},
    gap(){rows.push([]);},
    thead(hs){rows.push(hs.map(h=>({v:h,s:XS.HEADER})));},
    trow(cells){rows.push(cells);},
  };
}
// ── Excel/CSV Export Utility ──────────────────────────────────────────────
function exportToCSV(filename, rows, columns) {
  try {
  rows = rows || [];
  columns = columns || [];
  if (rows.length === 0) { alert("No data to export."); return; }
  if (!columns || columns.length === 0) { alert("No columns defined."); return; }
  const headers = columns.map(c => c.label);
  const NL = String.fromCharCode(10);
  const csvRows = rows.map(row =>
    columns.map(c => {
      let val = c.getValue ? c.getValue(row) : (row[c.key] ?? "");
      const str = String(val).replace(/"/g, '""');
      return (str.indexOf(",") >= 0 || str.indexOf(NL) >= 0 || str.indexOf('"') >= 0) ? ('"' + str + '"') : str;
    }).join(",")
  );
  const csv = [headers.join(",")].concat(csvRows).join(NL);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename + ".csv";
  a.click();
  URL.revokeObjectURL(url);
  } catch(e) { alert("Export error: " + e.message); }
}
