const GMAIL_CLIENT_ID_ENV=import.meta.env.VITE_GMAIL_CLIENT_ID||"";
// Loads ALL individual calls, from the company's first recorded call to
// today, DAY BY DAY. Each request is a shallow, indexed single-day lookup,
// so queries stay fast no matter how large history grows (deep OFFSET
// pagination over the whole table caused statement timeouts past ~50k
// rows). The company requirement is full history, always — if total volume
// ever strains the browser itself, per-call analysis moves server-side
// rather than trimming this window.
const CALL_LOAD_MAX_DAYS=730; // safety bound against junk dates, not a window
async function sbAllCallsWindow(){
  const fmt=new Intl.DateTimeFormat("en-CA",{timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"});
  let firstDate=null;
  try{const f=await sb("GET","callgrid_calls?select=date&order=date.asc&limit=1");firstDate=String(f?.[0]?.date||"").slice(0,10)||null;}catch(e){/* fall back to the bound */}
  const days=[]; const d=new Date();
  for(let i=0;i<CALL_LOAD_MAX_DAYS;i++){
    const ds=fmt.format(d);
    days.push(ds);
    if(firstDate&&ds<=firstDate)break;
    d.setDate(d.getDate()-1);
  }
  const out=[]; const BATCH=8;
  for(let i=0;i<days.length;i+=BATCH){
    const chunks=await Promise.all(days.slice(i,i+BATCH).map(async ds=>{
      const rows=[];
      for(let off=0;off<20000;off+=1000){
        const p=await sb("GET",`callgrid_calls?select=*&date=eq.${ds}&order=call_datetime.desc&limit=1000&offset=${off}`);
        rows.push(...(p||[]));
        if(!p||p.length<1000)break;
      }
      return rows;
    }));
    chunks.forEach(r=>out.push(...r));
  }
  return out;
}
async function sbAll(path) {
  // Fetches all rows from a table. Pages are requested in parallel batches
  // of 8 (instead of one-at-a-time), which cuts a large table's load from
  // ~1 round trip per 1,000 rows to ~1 per 8,000.
  const PAGE = 1000, BATCH = 8;
  const sep = path.includes("?") ? "&" : "?";
  const first = await sb("GET", `${path}${sep}limit=${PAGE}&offset=0`);
  let all = first || [];
  if (all.length < PAGE) return all;
  let offset = PAGE;
  while (true) {
    const offsets = Array.from({length: BATCH}, (_, i) => offset + i * PAGE);
    const pages = await Promise.all(offsets.map(o => sb("GET", `${path}${sep}limit=${PAGE}&offset=${o}`)));
    let done = false;
    for (const p of pages) {
      if (!p || p.length === 0) { done = true; break; }
      all = all.concat(p);
      if (p.length < PAGE) { done = true; break; }
    }
    if (done) break;
    offset += BATCH * PAGE;
  }
  return all;
}
// Refreshes the Supabase access token using the stored refresh_token, so an
// expired session renews silently instead of forcing a re-login. Returns the
// new access_token, or null if refresh fails (then the user must sign in again).
let _refreshInFlight=null;
async function refreshSession(){
  // De-dupe concurrent refreshes so a burst of 401s triggers only one refresh.
  if(_refreshInFlight)return _refreshInFlight;
  _refreshInFlight=(async()=>{
    try{
      const session=sessionStorage.getItem("nyala_session");
      if(!session)return null;
      const {refresh_token}=JSON.parse(session);
      if(!refresh_token)return null;
      const r=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{
        method:"POST",
        headers:{"Content-Type":"application/json",apikey:SUPABASE_ANON_KEY},
        body:JSON.stringify({refresh_token}),
      });
      if(!r.ok)return null;
      const data=await r.json();
      if(!data.access_token)return null;
      sessionStorage.setItem("nyala_session",JSON.stringify({access_token:data.access_token,refresh_token:data.refresh_token||refresh_token}));
      return data.access_token;
    }catch{return null;}
    finally{setTimeout(()=>{_refreshInFlight=null;},0);}
  })();
  return _refreshInFlight;
}
async function sb(method, path, body) {
  const session = sessionStorage.getItem("nyala_session");
  const token = session ? JSON.parse(session).access_token : SUPABASE_ANON_KEY;
  function buildOpts(tok){
    const o={method,headers:{"Content-Type":"application/json",apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${tok}`,...(method==="POST"?{Prefer:"return=representation"}:{})}};
    if(body)o.body=JSON.stringify(body);
    return o;
  }
  let r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,buildOpts(token));
  // Expired/invalid token → refresh once and retry, so users don't have to
  // log out and back in when their session times out mid-edit.
  if(r.status===401&&session){
    const fresh=await refreshSession();
    if(fresh){
      r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,buildOpts(fresh));
    }
  }
  if(!r.ok)throw new Error(await r.text());
  const t=await r.text();
  return t?JSON.parse(t):[];
}
async function sbAuth(method, path, body) {
  const r = await fetch(`${SUPABASE_URL}/auth/v1/${path}`, {
    method,
    headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await r.json();
  if (data.error) throw new Error(data.error.message || data.error);
  return data;
}
