// "YYYY-MM-DD" strings are parsed as UTC midnight by `new Date(...)`. Formatting
// that with toLocaleDateString() then converts to the browser's local timezone,
// which can display the WRONG calendar day (e.g. shows the 28th for a date
// picker value of the 29th, for anyone west of UTC). These helpers parse and
// re-serialize dates purely in local time so the calendar day never shifts.
function parseLocalDate(dateStr) {
  if (!dateStr) return null;
  const [y,m,d] = dateStr.slice(0,10).split("-").map(Number);
  return new Date(y, m-1, d);
}
function toDateStr(dateObj) {
  const y = dateObj.getFullYear();
  const m = String(dateObj.getMonth()+1).padStart(2,"0");
  const d = String(dateObj.getDate()).padStart(2,"0");
  return `${y}-${m}-${d}`;
}
function fmtDate(d) { if(!d) return "—"; return parseLocalDate(d).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}); }
