function fmtDatePdf(d) {
  if (!d) return "";
  const dt = parseLocalDate(d);
  if (!dt) return "";
  return `${dt.getMonth()+1}/${dt.getDate()}/${String(dt.getFullYear()).slice(-2)}`;
}
function computeInvoiceTermsLabel(row) {
  if (!row.invoice_date || !row.due_date) return row.due_date ? `Due ${fmtDatePdf(row.due_date)}` : "Due Upon Receipt";
  const inv = parseLocalDate(row.invoice_date);
  const due = parseLocalDate(row.due_date);
  const diffDays = Math.round((due - inv) / (1000*60*60*24));
  return diffDays <= 1 ? "Due Upon Receipt" : `Net ${diffDays}`;
}
function buildInvoiceLineDescription(row) {
  const period = row.billing_period || (row.period_start ? `${fmtDate(row.period_start)} - ${fmtDate(row.period_end)}` : "");
  const lines = [`Billable Calls${period?` - ${period}`:""}`];
  if (row.notes) lines.push(row.notes);
  return lines.join("\n");
}
function renderTermsAndConditionsPages(doc, margin, pageWidth, pageHeight) {
  let y = 56;
  doc.setFont("helvetica","bold"); doc.setFontSize(13); doc.setTextColor(20,20,20);
  doc.text(`${BRAND.name.toUpperCase()} TERMS AND CONDITIONS`, pageWidth/2, y, {align:"center"});
  y += 26;
  const maxWidth = pageWidth - margin*2;
  const bottomLimit = pageHeight - 50;
  TERMS_AND_CONDITIONS.forEach(section=>{
    if (section.title) {
      if (y > bottomLimit) { doc.addPage(); y = 50; }
      doc.setFont("helvetica","bold"); doc.setFontSize(10); doc.setTextColor(20,20,20);
      doc.text(section.title, margin, y);
      y += 15;
    }
    section.blocks.forEach(block=>{
      doc.setFont("helvetica","normal"); doc.setFontSize(8.5); doc.setTextColor(40,40,40);
      if (block.type==="p") {
        const lines = doc.splitTextToSize(block.text, maxWidth);
        lines.forEach(line=>{
          if (y > bottomLimit) { doc.addPage(); y = 50; }
          doc.text(line, margin, y);
          y += 11.5;
        });
        y += 5;
      } else if (block.type==="bullets") {
        block.items.forEach(item=>{
          const lines = doc.splitTextToSize(item, maxWidth - 16);
          lines.forEach((line,i)=>{
            if (y > bottomLimit) { doc.addPage(); y = 50; }
            doc.text(i===0?`•  ${line}`:`   ${line}`, margin + 6, y);
            y += 11.5;
          });
        });
        y += 5;
      }
    });
    y += 6;
  });
}
