      const metaPairs=[["Client",clientName],["Product",cpd.product||"—"],["Campaign",cpd.campaign_label||tc?.name||"—"],["Flight Dates",(cpd.flight_dates&&cpd.flight_dates!=="TBD")?cpd.flight_dates:(flight?.flight_start?`${fmtDate(flight.flight_start)} – ${fmtDate(flight.flight_end)}`:"TBD")],["Unit Length",cpd.unit_length||"—"],["Prepared By",cpd.prepared_by||"Nyala Labs"],["Plan Date",new Date().toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"})],["Status",cpd.status||"Draft"]];
      for(let i=0;i<metaPairs.length;i+=2){ const row=blankRow().slice(); row[0]={v:metaPairs[i][0]+":",s:4}; row[1]={v:metaPairs[i][1]}; if(metaPairs[i+1]&&nCol>3){ row[2]={v:metaPairs[i+1][0]+":",s:4}; row[3]={v:metaPairs[i+1][1]}; } out.push(row); if(metaPairs[i+1]&&nCol<=3){ const row2=blankRow().slice(); row2[0]={v:metaPairs[i+1][0]+":",s:4}; row2[1]={v:metaPairs[i+1][1]}; out.push(row2); } }
      out.push(blankRow());
      // KPI summary (label, value).
      const kpis=[["Total Investment",clientInvestment,true],["Total Spots",totSpots,false],["Networks",new Set(bookRows.map(r=>getNetworkName(r.line.network_id))).size,false],["Projected Calls",Math.round(tot.calls),false],["Proj. Cost / Call",isCashbuy?(tot.calls>0?clientClearedTot/tot.calls:0):totCpc,true],["Avg Unit Cost",totSpots>0?clientInvestment/totSpots:0,true]];
      kpis.forEach(k=>{ const row=blankRow().slice(); row[0]={v:k[0],s:4}; row[1]=k[2]?numCell(money2(k[1]),3):numCell(k[1],8); out.push(row); });
      out.push(blankRow());
      // Network table header.
