      const clientName=clients.find(cl=>tc&&(clientCampaigns.find(cc=>cc.tv_campaign_id===tc.id)?.client_id===cl.id))?.name || (tc?.name||"Client");
      const nets=[...new Set(bookRows.map(r=>getNetworkName(r.line.network_id)).filter(Boolean))];
      const totSpots=bookRows.reduce((s,r)=>s+r.spots,0);
      const totClearedSpots=bookRows.reduce((s,r)=>s+r.spots*r.clr,0);
