        d.text(clientName.toUpperCase(),M,28);
        d.setFont("helvetica","normal");d.setFontSize(8);d.setTextColor(230,210,214);
        d.text(cpd.product||"Direct Response Television",M,43);
        d.setFont("helvetica","bold");d.setFontSize(9.5);d.setTextColor(255,255,255);
        d.text(rightTitle,W-M,27,{align:"right"});
        d.setFont("helvetica","normal");d.setFontSize(8);d.setTextColor(230,210,214);
