      d.text("Media Plan & Investment Summary",M,y);
      y+=13;d.setFont("helvetica","normal");d.setFontSize(8.5);d.setTextColor(...gray);
      d.text(cpd.subtitle||"Direct Response Television • Call-Driven Acquisition",M,y);
      y+=14;
      const flightLabel=(()=>{ if(cpd.flight_dates&&cpd.flight_dates!=="TBD")return cpd.flight_dates; const fs=flight?.flight_start,fe=flight?.flight_end; return fs?`${fmtDate(fs)} – ${fmtDate(fe)}`:"TBD"; })();
      const meta=[
        [["CLIENT",clientName],["PRODUCT",cpd.product||"—"],["CAMPAIGN",cpd.campaign_label||tc?.name||"—"],["FLIGHT DATES",flightLabel]],
        [["UNIT LENGTH",cpd.unit_length||"—"],["PREPARED BY",cpd.prepared_by||"Nyala Labs"],["PLAN DATE",new Date().toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"})],["STATUS",cpd.status||"Draft"]],
      ];
