      // already baked into allCols' getters.
      const showDaypart=clientCols.daypart!==false;
      // Column set = the toggled columns, in allCols order. Network is forced on.
      const outCols=allCols.filter(c=>c.key==="network"||clientCols[c.key]);
      // Source rows: per-line, or aggregated per network when daypart is off.
      let srcRows;
      if(showDaypart){
        srcRows=bookRows;
      } else {
        const agg={};
        bookRows.forEach(r=>{ const nm=getNetworkName(r.line.network_id); if(!agg[nm])agg[nm]={line:r.line,eff:{...r.eff,daypart:""},creativeInfo:r.creativeInfo,spots:0,clearedSpots:0,gross:0,cleared:0,calls:0,revenue:0,profit:0}; const a=agg[nm]; a.spots+=r.spots; a.clearedSpots+=r.spots*r.clr; a.gross+=r.gross; a.cleared+=r.cleared; a.calls+=r.calls; a.revenue+=r.revenue; a.profit+=r.profit; if(r.eff.length_seconds)a.eff.length_seconds=r.eff.length_seconds; });
        srcRows=Object.values(agg).map(a=>({...a,cpc:a.calls>0?a.cleared/a.calls:0,margin:a.revenue>0?a.profit/a.revenue:0,rate:a.spots>0?a.gross/a.spots:0,cps:a.clearedSpots>0?a.calls/a.clearedSpots:0,clr:a.spots>0?a.clearedSpots/a.spots:0})).sort((x,y)=>y.cleared-x.cleared);
      }
      // Format a value for the PDF (currency columns get $ + commas).
