        weeks:()=>String(weeks),
        rate:()=>"$"+(totSpots>0?tot.gross/totSpots:0).toLocaleString(undefined,{maximumFractionDigits:0}),
        cps:()=>(totClearedSpots>0?tot.calls/totClearedSpots:0).toFixed(2),
        clear:()=>(totSpots>0?(totClearedSpots/totSpots*100):0).toFixed(0)+"%",
        clearedspots:()=>Math.floor(totClearedSpots).toLocaleString(),
        gross:()=>"$"+Math.round(tot.gross).toLocaleString(),
        cleared:()=>"$"+Math.round(clientClearedTot).toLocaleString(),
        pct:()=>"100.0%", calls:()=>Math.round(tot.calls).toLocaleString(),
        revenue:()=>"$"+Math.round(cSpend(tot.revenue)).toLocaleString(),
        cpc:()=>"$"+clientTotCpc.toFixed(2),
        profit:()=>"$"+Math.round(tot.profit).toLocaleString(),
