      const foot1="Spot counts reflect units as scheduled. Projected cleared spend represents anticipated cleared investment net of preemptions; actual cleared spend is reconciled post-flight against affidavit. Source: network rate quotes and historical response data supplied by "+(cpd.prepared_by||"Nyala Labs")+".";
      d.text(d.splitTextToSize(foot1,W-2*M),M,afterY);
      footer();
      // ===== PAGE 2 =====
      d.addPage();
      headerBand("ANALYSIS & TERMS");
      y=88;
      d.setFont("helvetica","bold");d.setFontSize(17);d.setTextColor(...maroon);d.text("Allocation & Efficiency Analysis",M,y);
      y+=13;d.setFont("helvetica","normal");d.setFontSize(8.5);d.setTextColor(...gray);
      d.text("Investment distribution and projected response efficiency by network.",M,y);
      y+=16;
      const panelW=(W-2*M-24)/2, panelX2=M+panelW+24;
