      const allocAll=netAgg.map(n=>({name:n.name,val:cSpend(n.cleared),pct:clientClearedTot>0?cSpend(n.cleared)/clientClearedTot*100:0})).sort((a,b)=>b.val-a.val);
      const effAll=netAgg.map(n=>({name:n.name,val:n.calls>0?cSpend(n.cleared)/n.calls:0})).filter(x=>x.val>0).sort((a,b)=>a.val-b.val);
      const CAP=15;
