  function clearFilters(){setSelClients([]);setSelCampaigns([]);setSelPublishers([]);setSelVerticals([]);setSelLeadTypes([]);setSelDurations([]);setFilterStart("");setFilterEnd("");}
  const hasFilters=selClients.length||selCampaigns.length||selPublishers.length||selVerticals.length||selLeadTypes.length||selDurations.length||filterStart||filterEnd;
