      const revKey = `${c.date}__${c.client_campaign_id||c.campaign}`;
      if(!callgridRevMap[revKey]) callgridRevMap[revKey]={date:c.date,client:c.client||"",campaign:c.campaign||"",client_campaign_id:c.client_campaign_id||null,calls:0,tot:0,revenue:0,pubMap:{}};
      if(isConnCall(c))callgridRevMap[revKey].tot+=1;
      if(isBillCall(c))callgridRevMap[revKey].calls+=1;
