                {arForm.type==="cashbuy"&&arForm.gross_spend&&arForm.markup_pct?`Auto: ${fmt$((parseFloat(arForm.gross_spend)||0)*(1+(parseFloat(arForm.markup_pct)||0)/100))}`:""}
