// ── ALERT BELL — open-alert feed, pop-up toasts, acknowledge ──────────────
function AlertBell({user}){
  const [open,setOpen]=useState(false);
  const [alerts,setAlerts]=useState([]);
  const [toasts,setToasts]=useState([]);
  const seenRef=React.useRef(null);
  const [lastRun,setLastRun]=useState(null);
  const load=React.useCallback(async()=>{
    try{
      const [rows,st]=await Promise.all([
        sb("GET","alerts?status=eq.open&order=fired_at.desc&limit=100"),
        sb("GET","ping_sync_state?key=eq.alert_engine&select=value").catch(()=>[]),
      ]);
      setLastRun(st?.[0]?.value?.last_run||null);
      setAlerts(rows||[]);
      let last=seenRef.current;
      if(last===null){try{last=localStorage.getItem("nyala_alerts_seen")||"";}catch(e){last="";}}
      const fresh=(rows||[]).filter(a=>a.fired_at>last);
      if(fresh.length&&last!==""){
        setToasts(t=>[...fresh.slice(0,4).map(a=>({id:a.id,severity:a.severity,message:a.message})),...t].slice(0,4));
      }
      const newest=(rows||[]).map(a=>a.fired_at).sort().pop()||last||"";
      seenRef.current=newest>(last||"")?newest:(last||"");
      try{localStorage.setItem("nyala_alerts_seen",seenRef.current);}catch(e){}
    }catch(e){/* alerts table may not exist yet */}
  },[]);
  useEffect(()=>{load();const t=setInterval(()=>{if(document.visibilityState==="visible")load();},60*1000);return()=>clearInterval(t);},[load]);
  useEffect(()=>{if(!toasts.length)return;const t=setTimeout(()=>setToasts(x=>x.slice(0,-1)),10000);return()=>clearTimeout(t);},[toasts]);
  async function resolve(id,status){try{await sb("PATCH",`alerts?id=eq.${id}`,{status,acked_at:new Date().toISOString(),acked_by:user?.id||user?.sub||null});setAlerts(a=>a.filter(x=>x.id!==id));}catch(e){alert(e.message);}}
  async function ackAll(){for(const a of alerts)await sb("PATCH",`alerts?id=eq.${a.id}`,{status:"acked",acked_at:new Date().toISOString(),acked_by:user?.id||user?.sub||null}).catch(()=>{});setAlerts([]);}
  const sevColor=s=>s==="critical"?C.red:s==="info"?C.accent:C.amber;
  const fmtT=ts=>new Date(ts).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit",timeZone:"America/New_York"});
  return <>
    <button onClick={()=>setOpen(o=>!o)} style={{width:"100%",background:alerts.length?`${C.amber}15`:"none",border:`1px solid ${alerts.length?C.amber:C.border}`,borderRadius:6,color:alerts.length?C.amber:C.sub,cursor:"pointer",fontSize:12,padding:"7px",marginBottom:8,fontWeight:alerts.length?700:400}}>
      🔔 Alerts{alerts.length?` (${alerts.length})`:""}
    </button>
    {open&&<div style={{position:"fixed",right:16,top:16,width:400,maxWidth:"calc(100vw - 32px)",maxHeight:"82vh",overflowY:"auto",background:C.surface,border:`1px solid ${C.border}`,borderRadius:12,boxShadow:"0 12px 40px rgba(0,0,0,0.35)",zIndex:300,padding:16}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
        <div style={{fontSize:14,fontWeight:700}}>Alerts</div>
        <div style={{display:"flex",gap:8}}>
          {alerts.length>0&&<Btn outline color={C.sub} onClick={ackAll} style={{padding:"4px 10px",fontSize:11}}>Ack All</Btn>}
          <Btn outline color={C.sub} onClick={()=>setOpen(false)} style={{padding:"4px 10px",fontSize:11}}>Close</Btn>
        </div>
      </div>
      {!alerts.length&&<div style={{color:C.sub,fontSize:13,padding:"16px 0",textAlign:"center"}}>No open alerts — all clear.</div>}
      {lastRun&&<div style={{fontSize:11,color:C.dim,textAlign:"center",marginBottom:8}}>Engine last checked {new Date(lastRun).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit",timeZone:"America/New_York"})} ET · runs every 15 min</div>}
      {alerts.map(a=><div key={a.id} style={{borderLeft:`3px solid ${sevColor(a.severity)}`,background:C.bg,borderRadius:8,padding:"10px 12px",marginBottom:8}}>
        <div style={{fontSize:12.5,color:C.text,lineHeight:1.45}}>{a.message}</div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:6}}>
          <span style={{fontSize:11,color:C.dim}}>{a.date} · {fmtT(a.fired_at)} ET</span>
          <div style={{display:"flex",gap:6}}>
            <Btn outline color={C.green} onClick={()=>resolve(a.id,"acked")} style={{padding:"3px 10px",fontSize:11}}>✓ Ack</Btn>
            <Btn outline color={C.muted} onClick={()=>{if(confirm("Ignore this alert? It won't fire again today for this subject (kept on record as ignored)."))resolve(a.id,"ignored");}} style={{padding:"3px 10px",fontSize:11}}>✕ Ignore</Btn>
          </div>
        </div>
      </div>)}
      <div style={{fontSize:11,color:C.dim,marginTop:4}}><b>Ack</b> = handled for now — if the problem persists, it re-alerts after the rule's cooldown. <b>Ignore</b> = silenced for the rest of the day, kept on record. Thresholds: Configuration → Notifications.</div>
    </div>}
    <div style={{position:"fixed",right:16,bottom:16,zIndex:310,display:"flex",flexDirection:"column",gap:8,maxWidth:380}}>
      {toasts.map(t=><div key={t.id} onClick={()=>{setToasts(x=>x.filter(y=>y.id!==t.id));setOpen(true);}} style={{cursor:"pointer",background:C.surface,border:`1px solid ${sevColor(t.severity)}`,borderLeft:`4px solid ${sevColor(t.severity)}`,borderRadius:10,padding:"10px 14px",boxShadow:"0 8px 30px rgba(0,0,0,0.35)",fontSize:12.5,color:C.text,lineHeight:1.45}}>
        <b style={{color:sevColor(t.severity)}}>⚠ Alert</b> — {t.message}
      </div>)}
    </div>
  </>;
}
export default function App() {
  // Load Google Identity Services for Gmail OAuth
  // Background syncing runs server-side on a Supabase Cron schedule
  // (every 15 min) — no browser needed. Manual sync stays in Actuals.
  useEffect(()=>{
    if(!document.getElementById("google-gsi")){
      const s=document.createElement("script");
      s.id="google-gsi";
      s.src="https://accounts.google.com/gsi/client";
      s.async=true;
      document.head.appendChild(s);
    }
  },[]);
  const [isDark,setIsDark]=useState(()=>localStorage.getItem("nyala_theme")!=="light");
  C = isDark ? DARK_THEME : LIGHT_THEME;
  card = makeCard();
  inputStyle = makeInput();
  function toggleTheme(){const next=!isDark;setIsDark(next);localStorage.setItem("nyala_theme",next?"dark":"light");}
  const [user,setUser]=useState(null);
  const [token,setToken]=useState(null);
  const [nav,setNav]=useState(()=>localStorage.getItem("nyala_nav")||"dashboard");
  function goNav(n){setNav(n);localStorage.setItem("nyala_nav",n);}
  const [analysisModule,setAnalysisModule]=usePersistentState("analysis_module","analysis");
  const [configModule,setConfigModule]=usePersistentState("config_module","config");
  const [peopleModule,setPeopleModule]=usePersistentState("people_module","team");
  // Pages folded into hubs: migrate anyone whose saved nav still points at
  // the old standalone ids.
  useEffect(()=>{
    if(["cashflow","perfreport","dispos","pingbids"].includes(nav)){setAnalysisModule(nav);goNav("analysis");}
    else if(nav==="integrations"){setConfigModule("integrations");goNav("config");}
    else if(["team","agents","hr"].includes(nav)){setPeopleModule(nav);goNav("people");}
  },[nav]);
  const [data,setData]=useState({arRows:[],apRows:[],invoiceLineItems:[],dailyTotals:[],dailyTotalsPub:[],actuals:[],pubActuals:[],callgridCalls:[],tvRows:[],tvInvoices:[],clients:[],publishers:[],networks:[],clientCampaigns:[],publisherCampaigns:[],campaignLinks:[],tvCampaigns:[],tvCampaignClients:[],tvCampaignNetworks:[],tvBookings:[],tvBuyLines:[],mediaPlans:[],tvLineCreatives:[],tvAirings:[],tvIOs:[],tvPhoneNumbers:[],tvNumberAssignments:[],tvCreatives:[],tvCreativeNumbers:[],tvApLedger:[],tvArLedger:[],pubCampaignRates:[],clientCampaignRates:[],onboardingChecklists:[],notifPrefs:[]});
  const [settings,setSettings]=useState(null);
  const [callgridConfig,setCallGridConfig]=useState(null);
  const [loading,setLoading]=useState(false);
  const [callsLoading,setCallsLoading]=useState(false);
  const [dataAt,setDataAt]=useState(null);
  const [globalFilters,setGlobalFilters]=usePersistentState("global_filters",{client:"All",publisher:"All",vertical:"All",lead_type:"All",duration:"All"});
  // Filter campaigns/data by global filters
  function filterByGlobal(campaigns, isClient=true) {
    return campaigns.filter(cc=>{
      if (globalFilters.vertical!=="All" && cc.vertical!==globalFilters.vertical) return false;
      if (globalFilters.lead_type!=="All" && cc.lead_type!==globalFilters.lead_type) return false;
      if (globalFilters.duration!=="All" && String(cc.duration_seconds)!==String(globalFilters.duration)) return false;
      return true;
    });
  }
  useEffect(()=>{
    const s=sessionStorage.getItem("nyala_session");
    if(s){try{
      const parsed=JSON.parse(s);
      // Validate the stored token; if it's expired, refresh it silently instead
      // of dropping the session (which forced a re-login on every return).
      fetch(`${SUPABASE_URL}/auth/v1/user`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${parsed.access_token}`}})
        .then(async r=>{
          if(r.ok){const u=await r.json();setUser(u);setToken(parsed.access_token);return;}
          const fresh=await refreshSession();
          if(fresh){const u=await(await fetch(`${SUPABASE_URL}/auth/v1/user`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${fresh}`}})).json();setUser(u);setToken(fresh);}
          else sessionStorage.removeItem("nyala_session");
        })
        .catch(()=>sessionStorage.removeItem("nyala_session"));
    }catch{}}
    const sv=localStorage.getItem("nyala_settings");if(sv)try{setSettings(JSON.parse(sv));}catch{}
    const rb=localStorage.getItem("nyala_callgrid");if(rb)try{setCallGridConfig(JSON.parse(rb));}catch{}
  },[]);
  // Optimistically update one row in a table in local state, WITHOUT a full
  // data reload. Used for in-place cell edits so the grid doesn't remount and
  // steal focus after every keystroke/commit. Pass the table key, row id, and
  // the changed fields.
  const patchRow=useCallback((table,id,patch)=>{
    setData(d=>{
      const rows=d[table];
      if(!Array.isArray(rows))return d;
      return {...d,[table]:rows.map(r=>r.id===id?{...r,...patch}:r)};
    });
  },[]);
  const loadData=useCallback(async()=>{
    if(!token) return;
    setLoading(true);
    try{
      let liveToken=token;
      async function get(path){
        let r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${liveToken}`}});
        if(r.status===401){
          const fresh=await refreshSession();
          if(fresh){liveToken=fresh;setToken(fresh);r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${fresh}`}});}
        }
        const t=await r.text();return t?JSON.parse(t):[];
      }
      const [arRows,apRows,invoiceLineItems,dailyTotals,dailyTotalsPub,actuals,pubActuals,tvCampaigns,tvCampaignClients,tvCampaignNetworks,tvBookings,tvBuyLines,mediaPlans,tvLineCreatives,tvAirings,tvIOs,tvPhoneNumbers,tvNumberAssignments,tvCreatives,tvCreativeNumbers,tvApLedger,tvArLedger,clients,publishers,networks,clientCampaigns,publisherCampaigns,campaignLinks,pubCampaignRates,clientCampaignRates,onboardingChecklists,notifPrefs]=await Promise.all([
        get("ar_ledger?order=created_at.desc"),
        get("ap_ledger?order=created_at.desc"),
        get("invoice_line_items?order=sort_order.asc"),
        sbAll("callgrid_daily_totals?order=date.desc"),
        sbAll("callgrid_daily_totals_pub?order=date.desc").catch(()=>[]),
        sbAll("actuals?order=date.desc"),
        sbAll("pub_actuals?order=date.desc"),
        get("tv_campaigns?order=created_at.desc"),
        get("tv_campaign_clients?select=*"),
        get("tv_campaign_networks?select=*"),
        get("tv_bookings?order=week_start.desc"),
        get("tv_buy_lines?order=created_at.desc"),
        get("media_plans?order=flight_start.desc"),
        get("tv_line_creatives?select=*"),
        sbAll("tv_airings?order=id.asc"),
        get("tv_ios?order=generated_at.desc"),
        get("tv_phone_numbers?order=created_at.desc"),
        get("tv_number_assignments?order=valid_from.desc"),
        get("tv_creatives?order=name"),
        get("tv_creative_numbers?order=created_at.desc"),
        get("tv_ap_ledger?order=created_at.desc"),
        get("tv_ar_ledger?order=created_at.desc"),
        get("clients?order=name"),
        get("publishers?order=name"),
        get("tv_networks?order=name"),
        get("client_campaigns?order=name"),
        get("publisher_campaigns?order=name"),
        get("campaign_links?select=*"),
        get("publisher_campaign_rates?order=effective_from.desc"),
        get("client_campaign_rates?order=effective_from.desc"),
        get("onboarding_checklists?select=*"),
        get("notification_preferences?select=*&order=created_at"),
      ]);
      const parsedCC=clientCampaigns.map(c=>({...c,volume_periods:typeof c.volume_periods==="string"?JSON.parse(c.volume_periods||"[]"):(c.volume_periods||[])}));
      // Resolve current names live from IDs (when present) so a rename in
      // Configuration immediately shows up on rows saved earlier, instead of
      // being frozen to whatever text was typed at save time.
      const resolvedAR = arRows.map(r=>({
        ...r,
        client: r.client_id ? (clients.find(c=>c.id===r.client_id)?.name || r.client) : r.client,
        campaign_name: r.client_campaign_id ? (parsedCC.find(c=>c.id===r.client_campaign_id)?.name || r.campaign_name) : r.campaign_name,
      }));
      const resolvedAP = apRows.map(r=>({
        ...r,
        publisher: r.publisher_id ? (publishers.find(p=>p.id===r.publisher_id)?.name || r.publisher) : r.publisher,
        campaign_name: r.publisher_campaign_id ? (publisherCampaigns.find(p=>p.id===r.publisher_campaign_id)?.name || r.campaign_name) : r.campaign_name,
      }));
      const resolvedActuals = actuals.map(r=>({
        ...r,
        client: r.client_id ? (clients.find(c=>c.id===r.client_id)?.name || r.client) : r.client,
        campaign: r.client_campaign_id ? (parsedCC.find(c=>c.id===r.client_campaign_id)?.name || r.campaign) : r.campaign,
      }));
      // Note: the legacy `publisher_name` column on pub_actuals actually stored
      // the publisher CAMPAIGN's name (a pre-existing mislabeling), not the
      // publisher company's name. We resolve both correctly here via IDs,
      // falling back to that legacy column only as a last resort for old rows.
      const resolvedPubActuals = pubActuals.map(r=>{
        const pc = r.publisher_campaign_id ? publisherCampaigns.find(p=>p.id===r.publisher_campaign_id) : null;
        const pub = r.publisher_id ? publishers.find(p=>p.id===r.publisher_id) : (pc ? publishers.find(p=>p.id===pc.publisher_id) : null);
        return { ...r, publisher: pub?.name || "—", campaign: pc?.name || r.publisher_name || "—" };
      });
      // Stage 1: everything except call history — the app paints and is
      // usable in a couple of seconds. Existing call data (if any) is kept
      // so background refreshes never blank out call-derived views.
      setData(d=>({arRows:resolvedAR,apRows:resolvedAP,invoiceLineItems,dailyTotals,dailyTotalsPub,actuals:resolvedActuals,pubActuals:resolvedPubActuals,callgridCalls:d.callgridCalls,tvCampaigns,tvCampaignClients,tvCampaignNetworks,tvBookings,tvBuyLines,mediaPlans,tvLineCreatives,tvAirings,tvIOs,tvPhoneNumbers,tvNumberAssignments,tvCreatives,tvCreativeNumbers,tvApLedger,tvArLedger,clients,publishers,networks,clientCampaigns:parsedCC,publisherCampaigns,campaignLinks,pubCampaignRates,clientCampaignRates,onboardingChecklists,notifPrefs}));
      setDataAt(new Date());
      // Stage 2: call history is by far the largest table — load it in the
      // background (parallel pages) and hydrate call-derived views when done.
      setCallsLoading(true);
      (async()=>{
        try{
          const callgridCalls=await sbAllCallsWindow();
          // Buyer-first attribution: in CallGrid the buyer IS the client, and
          // campaigns are shared across buyers — so resolve each call's client
          // from its buyer (target_name) first, then fall back to the
          // campaign-level mapping for calls with no buyer recorded.
          const buyerIdx = new Map();
          clients.forEach(c=>{
            [c.name, ...(String(c.callgrid_buyer_name||"").split(","))]
              .map(s=>String(s||"").trim().toLowerCase()).filter(Boolean)
              .forEach(k=>{ if(!buyerIdx.has(k)) buyerIdx.set(k, c); });
          });
          const resolvedCallGridCalls = callgridCalls.map(r=>{
            const cc = r.client_campaign_id ? parsedCC.find(c=>c.id===r.client_campaign_id) : null;
            const pc = r.publisher_campaign_id ? publisherCampaigns.find(p=>p.id===r.publisher_campaign_id) : null;
            const buyerClient = r.target_name ? buyerIdx.get(String(r.target_name).trim().toLowerCase()) : null;
            const cl = buyerClient || (cc ? clients.find(c=>c.id===cc.client_id) : null);
            const pub = pc ? publishers.find(p=>p.id===pc.publisher_id) : null;
            return {
              ...r,
              client: cl?.name || null,
              campaign: cc?.name || r.campaign_name,
              publisher: pub?.name || r.publisher_name,
            };
          });
          setData(d=>({...d,callgridCalls:resolvedCallGridCalls}));
        }catch(e){console.error(e);}
        setCallsLoading(false);
      })();
    }catch(e){console.error(e);}
    setLoading(false);
  },[token]);
  const [myRole,setMyRole]=useState(null);
  useEffect(()=>{
    if(!user){setMyRole(null);return;}
    (async()=>{try{
      const r=await sb("GET",`user_profiles?user_id=eq.${user.id||user.sub}&select=role`);
      setMyRole(r?.[0]?.role||"staff");
    }catch(e){console.error(e);setMyRole("staff");}})();
  },[user]);
  useEffect(()=>{if(myRole&&myRole!=="agent")loadData();},[loadData,myRole]);
  // nav persists in localStorage across logins on the same browser — never
  // land a role-scoped user on a page their role can't see
  useEffect(()=>{if(myRole&&NAV_BY_ROLE[myRole]&&!NAV_BY_ROLE[myRole].includes(nav)&&!["cashflow","perfreport","dispos","pingbids","integrations","team","agents","hr"].includes(nav))goNav("dashboard");},[myRole,nav]);
  // Watch integration_systems for new sync completions (cron, webhook, or a
  // colleague's manual run) and silently reload data — no hard refresh needed.
  const lastSeenSync=React.useRef(null);
  useEffect(()=>{
    if(!token||!myRole||myRole==="agent")return;
    const check=async()=>{
      if(document.visibilityState!=="visible")return;
      try{
        const rows=await sb("GET","integration_systems?select=last_ok_at");
        const newest=(rows||[]).map(r=>r.last_ok_at||"").sort().pop()||"";
        if(lastSeenSync.current===null){lastSeenSync.current=newest;return;}
        if(newest>lastSeenSync.current){lastSeenSync.current=newest;loadData();}
      }catch(e){/* transient */}
    };
    const t=setInterval(check,30*1000);
    return ()=>clearInterval(t);
  },[token,myRole,loadData]);
  function signOut(){sessionStorage.removeItem("nyala_session");setUser(null);setToken(null);}
  const [showPwModal,setShowPwModal]=useState(false);
  const [pwForm,setPwForm]=useState({newPassword:"",confirm:""});
  const [pwSaving,setPwSaving]=useState(false);
  const [pwError,setPwError]=useState("");
  async function changePassword(){
    if(!pwForm.newPassword||pwForm.newPassword.length<8){setPwError("Password must be at least 8 characters.");return;}
    if(pwForm.newPassword!==pwForm.confirm){setPwError("Passwords do not match.");return;}
    setPwSaving(true);setPwError("");
    try{
      const res=await fetch(`${SUPABASE_URL}/auth/v1/user`,{
        method:"PUT",
        headers:{"Content-Type":"application/json","apikey":SUPABASE_ANON_KEY,"Authorization":`Bearer ${token}`},
        body:JSON.stringify({password:pwForm.newPassword}),
      });
      if(!res.ok){const e=await res.json();throw new Error(e.message||"Failed to update password");}
      setShowPwModal(false);setPwForm({newPassword:"",confirm:""});
      alert("Password updated successfully.");
    }catch(e){setPwError(e.message);}
    setPwSaving(false);
  }
  function saveSettings(s){setSettings(s);localStorage.setItem("nyala_settings",JSON.stringify(s));}
  function saveCallGridConfig(r){setCallGridConfig(r);localStorage.setItem("nyala_callgrid",JSON.stringify(r));}
  if(!user) return <AuthScreen onAuth={(u,t)=>{setUser(u);setToken(t);}}/>;
  if(myRole===null) return <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:C.bg,color:C.sub,fontFamily:"'Inter',system-ui,sans-serif"}}>Loading…</div>;
  if(myRole==="agent") return <AgentWorkspace user={user} onSignOut={signOut}/>;
  const navItems=[
    {id:"dashboard",label:"Overview",icon:"◈"},{id:"sotu",label:"State of the Union",icon:"▥"},{id:"projections",label:"Projections",icon:"↗"},
    {id:"actuals",label:"Actuals",icon:"⊞"},{id:"analysis",label:"Analysis",icon:"⇄"},
    {id:"billing",label:"Billing",icon:"$"},
    {id:"clientreports",label:"External Reports",icon:"▤"},
    {id:"creative",label:"Creative Labs",icon:"✦"},
    {id:"tv",label:"TV Media",icon:"▣"},
    {id:"config",label:"Configuration",icon:"⚙"},
    {id:"crm",label:"CRM",icon:"◎"},
    {id:"people",label:"People",icon:"⊕"},
  ];
  const visibleNav=NAV_BY_ROLE[myRole]?navItems.filter(i=>NAV_BY_ROLE[myRole].includes(i.id)):navItems;
  return <div key={isDark?"dark":"light"} style={{display:"flex",minHeight:"100vh",background:pageBg(),color:C.text,fontFamily:"'Inter','Segoe UI',system-ui,sans-serif"}}>
    <div style={{width:220,background:`linear-gradient(180deg, ${C.surface}, ${C.bg})`,borderRight:`1px solid ${C.border}`,display:"flex",flexDirection:"column",flexShrink:0,position:"sticky",top:0,height:"100vh",overflowY:"auto"}}>
      <div style={{padding:"24px 20px 20px",borderBottom:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}><BrandWord size={24}/></div>
        <div style={{fontSize:11,color:C.sub,marginTop:2}}>Operations Dashboard</div>
      </div>
      <nav style={{flex:1,padding:"12px 8px"}}>
        {visibleNav.map(item=><button key={item.id} onClick={()=>goNav(item.id)} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"9px 12px",borderRadius:8,marginBottom:2,background:nav===item.id?`linear-gradient(90deg, ${C.accent}26, transparent)`:"transparent",border:"1px solid transparent",boxShadow:nav===item.id?`inset 3px 0 0 ${C.accent}`:"none",color:nav===item.id?C.accent:C.sub,fontSize:13,fontWeight:nav===item.id?600:400,cursor:"pointer",textAlign:"left"}}><span style={{fontSize:14,opacity:0.8}}>{item.icon}</span>{item.label}</button>)}
      </nav>
      <div style={{padding:"12px 12px 20px",borderTop:`1px solid ${C.border}`}}>
        <div style={{fontSize:11,color:C.sub,marginBottom:8,overflow:"hidden",textOverflow:"ellipsis"}}>{user.email}</div>
        <AlertBell user={user}/>
        <button onClick={()=>loadData()} disabled={loading} style={{width:"100%",background:"none",border:`1px solid ${C.border}`,borderRadius:6,color:C.sub,cursor:loading?"wait":"pointer",fontSize:12,padding:"7px",marginBottom:8}}>
          {loading?"Refreshing…":`↻ Refresh Data${dataAt?" · "+dataAt.toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"}):""}`}
        </button>
        <button onClick={toggleTheme} style={{width:"100%",background:"none",border:`1px solid ${C.border}`,borderRadius:6,color:C.sub,cursor:"pointer",fontSize:12,padding:"7px",marginBottom:8,display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
          {isDark?"☀ Light Mode":"🌙 Dark Mode"}
        </button>
        <button onClick={()=>{setPwForm({newPassword:"",confirm:""});setPwError("");setShowPwModal(true);}} style={{width:"100%",background:"none",border:`1px solid ${C.border}`,borderRadius:6,color:C.sub,cursor:"pointer",fontSize:12,padding:"7px",marginBottom:8}}>
          🔑 Change Password
        </button>
        <Btn onClick={signOut} outline color={C.muted} style={{width:"100%",fontSize:12}}>Sign Out</Btn>
      </div>
    </div>
    <div style={{flex:1,overflow:"auto",display:"flex",flexDirection:"column"}}>
      <GlobalFilters data={data} filters={globalFilters} onChange={setGlobalFilters} onClear={()=>setGlobalFilters({client:"All",publisher:"All",vertical:"All",lead_type:"All",duration:"All"})}/>
      <div style={{flex:1,overflow:"auto"}}>
      <div style={{maxWidth:"100%",padding:"20px 28px"}}>
        {loading&&<div style={{color:C.sub,marginBottom:16,fontSize:13}}>Loading…</div>}
        {!loading&&callsLoading&&<div style={{color:C.dim,marginBottom:16,fontSize:12}}>Loading call history in the background — call-based numbers fill in shortly…</div>}
        <ErrorBoundary key={nav}>
        {nav==="dashboard"&&<Dashboard data={data}/>}
        {nav==="sotu"&&<StateOfUnion data={data}/>}
        {nav==="creative"&&<CreativeLabs user={user}/>}
        {nav==="projections"&&<Projections clientCampaigns={data.clientCampaigns} publisherCampaigns={data.publisherCampaigns} campaignLinks={data.campaignLinks} settings={settings} onSaveSettings={saveSettings} tvCampaigns={data.tvCampaigns||[]} tvCampaignClients={data.tvCampaignClients||[]} tvCampaignNetworks={data.tvCampaignNetworks||[]} tvBookings={data.tvBookings||[]} callgridCalls={data.callgridCalls||[]} clientCampaignRates={data.clientCampaignRates||[]} pubCampaignRates={data.pubCampaignRates||[]} arRows={data.arRows||[]} apRows={data.apRows||[]}/>}
        {nav==="actuals"&&<Actuals actuals={data.actuals} pubActuals={data.pubActuals} callgridCalls={data.callgridCalls} clients={data.clients} publishers={data.publishers} clientCampaigns={filterByGlobal(data.clientCampaigns)} publisherCampaigns={filterByGlobal(data.publisherCampaigns,false)} campaignLinks={data.campaignLinks} onRefresh={loadData} callgridConfig={callgridConfig} onSaveCallGridConfig={saveCallGridConfig} globalFilters={globalFilters} tvBookings={data.tvBookings||[]} tvCampaigns={data.tvCampaigns||[]} tvCreatives={data.tvCreatives||[]} networks={data.networks||[]}/>}
        {nav==="analysis"&&(()=>{
          const allowed=NAV_BY_ROLE[myRole]&&ANALYSIS_MODS_BY_ROLE[myRole]
            ?ANALYSIS_MODULES.filter(m=>ANALYSIS_MODS_BY_ROLE[myRole].includes(m.id))
            :ANALYSIS_MODULES;
          const mod=allowed.some(m=>m.id===analysisModule)?analysisModule:allowed[0]?.id;
          return <div>
            <div style={{display:"flex",gap:4,marginBottom:20,flexWrap:"wrap",borderBottom:`1px solid ${C.border}`,paddingBottom:12}}>
              {allowed.map(m=><button key={m.id} onClick={()=>setAnalysisModule(m.id)}
                style={{background:mod===m.id?C.accent:"transparent",color:mod===m.id?C.accentFg:C.sub,border:`1px solid ${mod===m.id?C.accent:C.border}`,borderRadius:6,padding:"7px 14px",fontSize:13,fontWeight:600,cursor:"pointer"}}>{m.label}</button>)}
            </div>
            {mod==="analysis"&&<Analysis arRows={data.arRows} apRows={data.apRows} actuals={data.actuals} callgridCalls={data.callgridCalls||[]} clientCampaigns={filterByGlobal(data.clientCampaigns)} publisherCampaigns={filterByGlobal(data.publisherCampaigns,false)} campaignLinks={data.campaignLinks} settings={settings} globalFilters={globalFilters} clients={data.clients} publishers={data.publishers} tvBookings={data.tvBookings||[]} tvCampaigns={data.tvCampaigns||[]} tvCreatives={data.tvCreatives||[]} networks={data.networks||[]}/>}
            {mod==="cashflow"&&<CashFlow clients={data.clients||[]} publishers={data.publishers||[]} clientCampaigns={data.clientCampaigns||[]} publisherCampaigns={data.publisherCampaigns||[]} callgridCalls={data.callgridCalls||[]}/>}
            {mod==="perfreport"&&<PerfReport clients={data.clients||[]} publishers={data.publishers||[]} clientCampaigns={data.clientCampaigns||[]} publisherCampaigns={data.publisherCampaigns||[]} callgridCalls={data.callgridCalls||[]} dailyTotals={data.dailyTotals||[]} dailyTotalsPub={data.dailyTotalsPub||[]} onRefresh={loadData}/>}
            {mod==="dispos"&&<Dispositions clients={data.clients||[]} callgridCalls={data.callgridCalls||[]} user={user}/>}
            {mod==="pingbids"&&<PingsBids/>}
          </div>;
        })()}
        {nav==="clientreports"&&<ExternalReports clients={data.clients} clientCampaigns={data.clientCampaigns||[]} arRows={data.arRows||[]} callgridCalls={data.callgridCalls||[]} actuals={data.actuals||[]} dailyTotals={data.dailyTotals||[]} onRefresh={loadData}/>}
        {nav==="billing"&&<Billing arRows={data.arRows} apRows={data.apRows} invoiceLineItems={data.invoiceLineItems||[]} onRefresh={loadData} clients={data.clients} publishers={data.publishers} clientCampaigns={filterByGlobal(data.clientCampaigns)} publisherCampaigns={filterByGlobal(data.publisherCampaigns,false)} pubActuals={data.pubActuals} actuals={data.actuals} callgridCalls={data.callgridCalls||[]} globalFilters={globalFilters} tvApLedger={data.tvApLedger||[]} tvArLedger={data.tvArLedger||[]} tvCampaigns={data.tvCampaigns||[]} networks={data.networks||[]}/>}
        {nav==="tv"&&<TVBooking tvCampaigns={data.tvCampaigns} tvCampaignClients={data.tvCampaignClients} tvCampaignNetworks={data.tvCampaignNetworks} tvBookings={data.tvBookings} tvBuyLines={data.tvBuyLines||[]} mediaPlans={data.mediaPlans||[]} tvLineCreatives={data.tvLineCreatives||[]} tvAirings={data.tvAirings||[]} callgridCalls={data.callgridCalls||[]} tvIOs={data.tvIOs||[]} tvPhoneNumbers={data.tvPhoneNumbers||[]} tvNumberAssignments={data.tvNumberAssignments||[]} tvCreatives={data.tvCreatives||[]} tvCreativeNumbers={data.tvCreativeNumbers||[]} tvApLedger={data.tvApLedger||[]} tvArLedger={data.tvArLedger||[]} networks={data.networks||[]} clients={data.clients||[]} clientCampaigns={data.clientCampaigns||[]} onRefresh={loadData} patchRow={patchRow}/>}
        {nav==="config"&&(()=>{
          const allowed=NAV_BY_ROLE[myRole]&&CONFIG_MODS_BY_ROLE[myRole]
            ?CONFIG_MODULES.filter(m=>CONFIG_MODS_BY_ROLE[myRole].includes(m.id))
            :CONFIG_MODULES;
          const mod=allowed.some(m=>m.id===configModule)?configModule:allowed[0]?.id;
          return <div>
            <div style={{display:"flex",gap:4,marginBottom:20,flexWrap:"wrap",borderBottom:`1px solid ${C.border}`,paddingBottom:12}}>
              {allowed.map(m=><button key={m.id} onClick={()=>setConfigModule(m.id)}
                style={{background:mod===m.id?C.accent:"transparent",color:mod===m.id?C.accentFg:C.sub,border:`1px solid ${mod===m.id?C.accent:C.border}`,borderRadius:6,padding:"7px 14px",fontSize:13,fontWeight:600,cursor:"pointer"}}>{m.label}</button>)}
            </div>
            {mod==="config"&&<Configuration clients={data.clients||[]} publishers={data.publishers||[]} clientCampaigns={data.clientCampaigns||[]} publisherCampaigns={data.publisherCampaigns||[]} campaignLinks={data.campaignLinks||[]} pubCampaignRates={data.pubCampaignRates||[]} clientCampaignRates={data.clientCampaignRates||[]} notifPrefs={data.notifPrefs||[]} onRefresh={loadData}/>}
            {mod==="integrations"&&<Integrations onRefresh={loadData}/>}
          </div>;
        })()}
        {nav==="crm"&&<CRM clients={data.clients||[]} publishers={data.publishers||[]} clientCampaigns={data.clientCampaigns||[]} publisherCampaigns={data.publisherCampaigns||[]} currentUser={user}/>}
        {nav==="people"&&(()=>{
          const allowed=NAV_BY_ROLE[myRole]&&PEOPLE_MODS_BY_ROLE[myRole]
            ?PEOPLE_MODULES.filter(m=>PEOPLE_MODS_BY_ROLE[myRole].includes(m.id))
            :PEOPLE_MODULES;
          const mod=allowed.some(m=>m.id===peopleModule)?peopleModule:allowed[0]?.id;
          return <div>
            <div style={{display:"flex",gap:4,marginBottom:20,flexWrap:"wrap",borderBottom:`1px solid ${C.border}`,paddingBottom:12}}>
              {allowed.map(m=><button key={m.id} onClick={()=>setPeopleModule(m.id)}
                style={{background:mod===m.id?C.accent:"transparent",color:mod===m.id?C.accentFg:C.sub,border:`1px solid ${mod===m.id?C.accent:C.border}`,borderRadius:6,padding:"7px 14px",fontSize:13,fontWeight:600,cursor:"pointer"}}>{m.label}</button>)}
            </div>
            {mod==="team"&&<Team currentUser={user}/>}
            {mod==="agents"&&<Agents callgridCalls={data.callgridCalls||[]} user={user}/>}
            {mod==="hr"&&<HRPortal user={user} isAdmin={myRole==="admin"}/>}
          </div>;
        })()}
        </ErrorBoundary>
      </div>
      </div>
    </div>
    {showPwModal&&<Modal title="Change Password" onClose={()=>setShowPwModal(false)}>
      <Field label="New Password">
        <Input type="password" value={pwForm.newPassword} onChange={e=>setPwForm({...pwForm,newPassword:e.target.value})} placeholder="At least 8 characters"/>
      </Field>
      <Field label="Confirm New Password">
        <Input type="password" value={pwForm.confirm} onChange={e=>setPwForm({...pwForm,confirm:e.target.value})} placeholder="Re-enter new password"/>
      </Field>
      {pwError&&<div style={{fontSize:12,color:C.red,marginTop:8}}>{pwError}</div>}
      <div style={{display:"flex",gap:10,justifyContent:"flex-end",marginTop:16}}>
        <Btn outline color={C.sub} onClick={()=>setShowPwModal(false)}>Cancel</Btn>
        <Btn onClick={changePassword} disabled={pwSaving}>{pwSaving?"Updating…":"Update Password"}</Btn>
      </div>
    </Modal>}
  </div>;
}
